            pcall(function() lf.GetCameraData = R.origGCD end)
        end
    end
    R.hookedLF, R.origGCD = nil, nil
end
R.Rewrite = function(self, data)
    if not (R.On and R.target and gunOf(self)) then return nil end
    R.lastShot = tick()
    R.firedAt = R.firedAt or tick()
    local out = rewrite(data)
    if out == data then return nil end
    return out
end
local function install(lf)
    local orig = lf.GetCameraData
    if type(orig) ~= "function" then return end
    R.hookedLF, R.origGCD = lf, orig
    lf.GetCameraData = function(self, ...)
        local res = orig(self, ...)
        if select("#", ...) == 0 and self == R.hookedLF then
            local ok, out = pcall(R.Rewrite, self, res)
            if ok and out then return out end
        end
        return res
    end
end
local function hold(hrp, cf)
    hrp.CFrame = cf
    hrp.AssemblyLinearVelocity = Vector3.zero
    hrp.AssemblyAngularVelocity = Vector3.zero
end
local MINE_TAG = "SubspaceTripmine"
local BODY = Vector3.new(1.5, 3, 1.5)
local function enemyMines()
    local out = {}
    if not R.AvoidMines then return out end
    local myTeam = teamOf(FC.LocalFighter, player)
    for _, mine in ipairs(CollectionService:GetTagged(MINE_TAG)) do
        if mine:IsDescendantOf(workspace) and mine:GetAttribute("PlacedByUserID") ~= player.UserId then
            local t = mine:GetAttribute("TeamID")
            if not (myTeam ~= nil and t ~= nil and t == myTeam) then
                local hb = mine:FindFirstChild("Hitbox")
                if hb and not hb:IsA("BasePart") then hb = hb:FindFirstChildWhichIsA("BasePart", true) end
                if hb then out[#out + 1] = hb end
            end
        end
    end
    return out
end
local function safeAt(pos, mines)
    local pad = Vector3.new(R.MineMargin, R.MineMargin, R.MineMargin)
    for _, hb in ipairs(mines) do
        local rel = hb.CFrame:PointToObjectSpace(pos)
        local half = hb.Size / 2 + BODY + pad
        if math.abs(rel.X) < half.X and math.abs(rel.Y) < half.Y and math.abs(rel.Z) < half.Z then return false end
    end
    return true
end
local losParams = RaycastParams.new()
losParams.FilterType = Enum.RaycastFilterType.Exclude
local function clearShot(from, m, to, ignore)
    local list = { m }
    if player.Character then list[#list + 1] = player.Character end
    for _, x in ipairs(ignore or {}) do list[#list + 1] = x end
    losParams.FilterDescendantsInstances = list
    local hit = workspace:Raycast(from, to - from, losParams)
    if hit and hit.Instance.Anchored and hit.Instance.CanCollide then return false, "blocked by " .. hit.Instance.Name end
    return true
end
local function shieldRaw(m)
    local f = fighterOf(m)
    if not f then return nil end
    local side
    pcall(function()
        local eq = f.EquippedItem
        for _, it in pairs(f.Items or {}) do
            if type(it) == "table" and (it.Name == "Riot Shield" or (type(it.Info) == "table" and it.Info.AmmoType == "Shield")) then
                local ammo = 1
                pcall(function() ammo = it:Get("Ammo") end)
                if not (type(ammo) == "number" and ammo <= 0) then
                    side = (it == eq) and "front" or "back"
                end
            end
        end
    end)
    return side
end
R.shieldRaw = shieldRaw
local function shieldSide(m)
    if R.ShieldMode ~= "Go around" then return nil end
    return shieldRaw(m)
end
local spotParams = OverlapParams.new()
spotParams.FilterType = Enum.RaycastFilterType.Exclude
spotParams.RespectCanCollide = false
local downParams = RaycastParams.new()
downParams.FilterType = Enum.RaycastFilterType.Exclude
local BAD_NAMES = { "barrier", "kill", "bound", "void", "death", "lava" }
local function charList()
    local list = {}
    for _, pl in ipairs(Players:GetPlayers()) do if pl.Character then list[#list + 1] = pl.Character end end
    for _, n in ipairs({ "HurtEffect", "ShootingRangeEntities" }) do
        local f = workspace:FindFirstChild(n)
        if f then list[#list + 1] = f end
    end
    local cam = workspace.CurrentCamera
    if cam then list[#list + 1] = cam end
    return list
end
local function badName(part)
    local n = part:GetFullName():lower()
    for _, w in ipairs(BAD_NAMES) do
        if n:find(w, 1, true) then return true end
    end
    return false
end
local function killName(part)
    local n = part:GetFullName():lower()
    for _, w in ipairs({ "kill", "void", "death", "lava" }) do
        if n:find(w, 1, true) then return true end
    end
    return false
end
local function spotOK(pos, ignore)
    spotParams.FilterDescendantsInstances = ignore
    local ok, parts = pcall(function() return workspace:GetPartBoundsInBox(CFrame.new(pos), Vector3.new(2.5, 5, 2.5), spotParams) end)
    if ok then
        for _, p in ipairs(parts) do
            if p.Anchored then
                if badName(p) then return false, "barrier " .. p.Name end
                if p.CanCollide and p.Transparency < 1 then return false, "wall " .. p.Name end
            end
        end
    end
    downParams.FilterDescendantsInstances = ignore
    local hit = workspace:Raycast(pos, Vector3.new(0, -120, 0), downParams)
    if not hit then return false, "no floor" end
    if hit.Instance.Anchored and killName(hit.Instance) then return false, "kill floor " .. hit.Instance.Name end
    return true
end
local function spots(thrp, head, side)
    local list = {}
    local look = thrp.CFrame.LookVector * Vector3.new(1, 0, 1)
    look = look.Magnitude > 0.01 and look.Unit or Vector3.zAxis
    local dir = side == "behind" and -look or side == "front" and look or nil
    if dir then
        for _, h in ipairs({ 0, 3, 6 }) do list[#list + 1] = head + dir * 3.5 + Vector3.new(0, 2 + h, 0) end
    else
        for _, h in ipairs({ 0, 2, 4, 7, 10, 14, 18 }) do list[#list + 1] = head + Vector3.new(0, 2 + h, 0) end
    end
    for _, r in ipairs({ 4, 7, 11 }) do
        for k = 0, 7 do
            local a = k * math.pi / 4
            local d = Vector3.new(math.cos(a), 0, math.sin(a))
            if not dir or d:Dot(dir) > 0.2 then
                list[#list + 1] = head + d * r + Vector3.new(0, 3.5, 0)
            end
        end
    end
    return list
end
local function approachSide(m)
    local blockFront = R.KatanaMode == "Go behind" and deflecting(m)
    local shield = shieldSide(m)
    if shield == "front" then blockFront = true end
    local blockBack = shield == "back"
    if shield and R.shieldLogFor ~= m then
        R.shieldLogFor = m
        log(("SHIELD %s on %s"):format(m.Name, shield))
    end
    if blockFront and blockBack then return nil end
    if blockFront then return "behind" end
    if blockBack then return "front" end
    return nil
end
local function placeCF(m, mines, hrp)
    local thrp = m:FindFirstChild("HumanoidRootPart")
    local aimAt = aimPoint(m)
    if not (thrp and aimAt) then return nil end
    local _, yaw = hrp.CFrame:ToEulerAnglesYXZ()
    local function finish(pos)
        local flat = (aimAt - pos) * Vector3.new(1, 0, 1)
        if flat.Magnitude > 0.5 then yaw = math.atan2(-flat.X, -flat.Z) end
        return CFrame.new(pos) * CFrame.Angles(0, yaw, 0)
    end
    local side = approachSide(m)
    local inside = thrp.Position + Vector3.new(0, R.Height, 0)
    if not side and (#mines == 0 or safeAt(inside, mines)) then
        R.spotCache = { m = m, off = inside - aimAt, at = tick(), inside = true }
        return finish(inside)
    end
    local c = R.spotCache
    if c and c.m == m and not c.inside and tick() - c.at < 0.15 then
        return finish(aimAt + c.off)
    end
    local list = spots(thrp, aimAt, side)
    if side then
        for _, h in ipairs({ 0, 2, 4, 7, 10 }) do list[#list + 1] = aimAt + Vector3.new(0, 2 + h, 0) end
        if #mines == 0 or safeAt(inside, mines) then
            R.spotCache = { m = m, off = inside - aimAt, at = tick(), inside = true }
            local ignoreSide = charList()
            for _, pos in ipairs(list) do
                if spotOK(pos, ignoreSide) and clearShot(pos + Vector3.new(0, 1.5, 0), m, aimAt, ignoreSide) then
                    R.spotCache = { m = m, off = pos - aimAt, at = tick() }
                    return finish(pos)
                end
            end
            return finish(inside)
        end
    end
    local ignore = charList()
    local why = {}
    for i, pos in ipairs(list) do
        local straight = ((pos - aimAt) * Vector3.new(1, 0, 1)).Magnitude < 0.5
        local good, reason = true, nil
        if #mines > 0 and not safeAt(pos, mines) then good, reason = false, "mine" end
        if good then good, reason = spotOK(pos, ignore) end
        if good and not straight then good, reason = clearShot(pos + Vector3.new(0, 1.5, 0), m, aimAt, ignore) end
        if not good and #why < 6 then why[#why + 1] = ("%d:%s"):format(i, tostring(reason)) end
        if good then
            if i > 1 and R.avoidLogFor ~= m then
                R.avoidLogFor = m
                log(("MOVED %s spot %d (%s) because %s"):format(m.Name, i, straight and "above" or "side", table.concat(why, ", ")))
            end
            R.spotCache = { m = m, off = pos - aimAt, at = tick() }
            return finish(pos)
        end
    end
    if R.blockLogFor ~= m then
        R.blockLogFor = m
        log(("NOSPOT %s: %s"):format(m.Name, table.concat(why, ", ")))
    end
    return nil, (#mines > 0) and "mine" or "blocked"
end
local function parkCF()
    local base = R.startCF and R.startCF.Position or Vector3.zero
    return CFrame.new(base + Vector3.new(R.HideDist, 40, R.HideDist))
end
local function releaseCamera()
