end
for _, d in ipairs(workspace:GetChildren()) do trackDrop(d) end
R.conns.dropAdd = workspace.ChildAdded:Connect(trackDrop)
R.conns.dropRem = workspace.ChildRemoved:Connect(function(d)
    R.drops[d] = nil
    R.dropTried[d] = nil
end)
local function nextDrop(hrp, near, since)
    local mines = enemyMines()
    local best, bd
    for d, t in pairs(R.drops) do
        if not d.Parent then
            R.drops[d] = nil
        elseif tick() - t < 20 and not R.dropTried[d] and (#mines == 0 or safeAt(d.Position, mines)) then
            local ok
            if near then
                ok = t >= since - 0.5 and (d.Position - near).Magnitude < 25
            else
                ok = (d.Position - hrp.Position).Magnitude < R.LootRange
            end
            local dist = (d.Position - hrp.Position).Magnitude
            if ok and (not bd or dist < bd) then best, bd = d, dist end
        end
    end
    return best
end
R.conns.place = RunService.Stepped:Connect(function()
    local phase = matchPhase()
    if phase ~= R.phase then
