local function aimAngles(from, to)
    local d = to - from
    local flat = Vector3.new(d.X, 0, d.Z).Magnitude
    local yaw = flat > 0.35 and math.atan2(-d.X, -d.Z) or (CC and CC.Rotation.Y or 0)
    return math.clamp(math.atan2(d.Y, flat), -1.569, 1.569), yaw, d.Magnitude
end
RunService:BindToRenderStep(AIM_STEP, Enum.RenderPriority.Camera.Value - 1, function()
    if not (R.On and R.AimCam and R.target and CC) then return end
    local cam = workspace.CurrentCamera
    local to = aimPoint(R.target)
    if not (cam and to) then return end
    local pitch, yaw, dist = aimAngles(cam.CFrame.Position, to)
    if dist < 0.05 then return end
    pcall(function() CC.Rotation = Vector2.new(pitch, yaw) end)
end)
RunService:BindToRenderStep(AIM_STEP .. "Lock", Enum.RenderPriority.Camera.Value + 1, function()
    if not (R.On and R.AimCam and R.target) then return end
