}
_G.RivalsHub.OrigKatana = orig
local function info(it, key, fallback)
    local v
    pcall(function() v = it.Info[key] end)
    return type(v) == "number" and v or fallback
end
local function mark(it, t)
    K.marks[it] = math.max(K.marks[it] or 0, tick() + t)
end
Katana._StartDeflecting = function(self, ...)
    if K.alive then pcall(mark, self, info(self, "DeflectDuration", 1)) end
    return orig.start(self, ...)
end
Katana._StopDeflecting = function(self, ...)
    if K.alive then K.marks[self] = nil end
    return orig.stop(self, ...)
end
Katana.ReplicateFromServer = function(self, kind, ...)
    if K.alive then
        if kind == "StartAiming" then
            pcall(mark, self, info(self, "DeflectDuration", 1))
        elseif kind == "DeflectHit" then
            pcall(mark, self, 0.3)
