end
function K.IsDeflecting(char)
    if not (K.alive and char) then return false end
    local item
    pcall(function()
        local f = FighterController:GetFighter(char)
        item = f and f.EquippedItem
    end)
    if not item then return false end
    local m = K.marks[item]
    local active = m and m > tick()
    if not active then
        local ok, dc = pcall(rawget, item, "_deflect_cooldown")
        active = ok and type(dc) == "number" and tick() < dc - info(item, "DeflectCooldown", 4)
    end
    if not active then return false end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    local cam = workspace.CurrentCamera
    if not (hrp and cam) then return true end
    local to = (cam.CFrame.Position - hrp.Position) * Vector3.new(1, 0, 1)
    local look = hrp.CFrame.LookVector * Vector3.new(1, 0, 1)
    if to.Magnitude < 0.1 or look.Magnitude < 0.1 then return true end
    return look.Unit:Dot(to.Unit) > -0.1
end
function K.Unload()
    K.alive = false
    Katana._StartDeflecting, Katana._StopDeflecting, Katana.ReplicateFromServer = orig.start, orig.stop, orig.rep
    _G.RivalsKatana = nil
end
