local HttpService = game:GetService("HttpService")
local Players = game:GetService("Players")
local lp = Players.LocalPlayer
local function notify(m) Library:Notify({ Title = "COMBO_WICK", Description = tostring(m), Time = 3 }) end
local FEEDBACK_URL     = "https://v0-secure-discord-proxy.vercel.app/api/v2sender"
local FEEDBACK_VERSION = "rivals-hub-1.0"
local _request = request or (syn and syn.request) or http_request
local function fbTrim(s) return (tostring(s or ""):gsub("^%s*(.-)%s*$", "%1")) end
local function fbHWID()
    local ok, id = pcall(function() return game:GetService("RbxAnalyticsService"):GetClientId() end)
    if ok and type(id) == "string" and id ~= "" then return id end
    return tostring(lp and lp.UserId or 0)
end
local FB_HWID = fbHWID()
local FB_ERRMAP = {
    empty = L["The message is empty."], no_links = L["Links are not allowed."],
    too_long = L["The message is too long (500 characters maximum)."],
    rate_limited = L["You have reached the limit of 3 messages. Please try again later."],
    busy = L["The server is busy. Please try again."], banned = L["You are not allowed to send feedback."],
    discord_error = L["Sending failed. Please try again."], network = L["Network error."],
    no_request = L["Your executor cannot send requests."], bad_response = L["The server returned an unexpected response."],
    unreachable = L["Your executor cannot reach the server (TLS error). Please try a different executor."],
}
local function sendFeedback(ftype, msg)
    if not _request then return false, "no_request" end
    local ok, res = pcall(function()
        return _request({
            Url = FEEDBACK_URL, Method = "POST",
            Headers = { ["Content-Type"] = "application/json" },
            Body = HttpService:JSONEncode({
                type = ftype, message = msg, hwid = FB_HWID,
                placeId = tostring(game.PlaceId), username = lp and lp.Name or "?",
                version = FEEDBACK_VERSION,
            }),
        })
    end)
    if not ok or not res then return false, "network" end
    if type(res) == "string" then return false, "unreachable" end
    if type(res) ~= "table" then return false, "network" end
    local code = res.StatusCode or res.status_code or res.Status or res.status
    if type(code) == "number" and code ~= 200 and code ~= 201 and code ~= 204 then return false, "http_" .. tostring(code) end
    local body = res.Body or res.body
    if type(body) ~= "string" or body == "" then return false, "bad_response" end
    local dok, data = pcall(function() return HttpService:JSONDecode(body) end)
    if not dok or type(data) ~= "table" then return false, "bad_response" end
    if data.success == true then return true end
    return false, tostring(data.error or "unknown")
end
local FG = Tab:AddLeftGroupbox(L["Suggestions / Help"], "message-square")
FG:AddDropdown("FeedbackType", { Text = L["Type"], Values = { "Suggestion", "Bug", "Help" }, Default = "Suggestion" })
FG:AddInput("FeedbackMsg", { Default = "", Numeric = false, Finished = false, ClearTextOnFocus = false, Text = L["Message"], Placeholder = L["Type your message (500 characters maximum, no links)"] })
local fbStatus = FG:AddLabel("", true)
local FEEDBACK_COOLDOWN, lastFeedback = 20, 0
FG:AddButton({
    Text = L["Send"],
    Func = function()
        local now = tick()
        if now - lastFeedback < FEEDBACK_COOLDOWN then
            pcall(function() fbStatus:SetText(string.format(L["Please wait %d seconds before sending again."], math.ceil(FEEDBACK_COOLDOWN - (now - lastFeedback)))) end)
            return
        end
        local ftype = tostring((Opt.FeedbackType and Opt.FeedbackType.Value) or "Suggestion"):lower()
        local msg = fbTrim((Opt.FeedbackMsg and Opt.FeedbackMsg.Value) or "")
        if msg == "" then pcall(function() fbStatus:SetText(L["The message is empty."]) end); return end
        if #msg > 500 then pcall(function() fbStatus:SetText(L["The message is too long (500 characters maximum)."]) end); return end
        local low = msg:lower()
        if low:find("http", 1, true) or low:find("discord.gg", 1, true) or low:find("www.", 1, true) or low:find(".gg/", 1, true) then
            pcall(function() fbStatus:SetText(L["Links are not allowed."]) end); return
        end
        pcall(function() fbStatus:SetText(L["Sending..."]) end)
        task.spawn(function()
            local sok, err = sendFeedback(ftype, msg)
            if sok then
                lastFeedback = tick()
                pcall(function() fbStatus:SetText(L["Sent. Thank you!"]) end)
                pcall(function() Opt.FeedbackMsg:SetValue("") end)
                notify(L["Your feedback was sent. Thank you!"])
            else
                pcall(function() fbStatus:SetText(FB_ERRMAP[err] or (L["Failed to send: "] .. tostring(err))) end)
            end
        end)
    end,
})
FG:AddLabel(L["Maximum 3 messages per hour. No links or mentions."], true)
local HelpGroup = Tab:AddRightGroupbox(L["Help / FAQ"], "life-buoy")
HelpGroup:AddLabel(L["Have a suggestion or found a bug?\nChoose a type, type your message, and press Send."], true)
end)
