        if savedShadows == nil then savedShadows = Lighting.GlobalShadows end
        if savedFog == nil then savedFog = Lighting.FogEnd end
        pcall(function() if savedQuality == nil then savedQuality = settings().Rendering.QualityLevel end end)
        pcall(function() Lighting.GlobalShadows = false end)
        pcall(function() Lighting.FogEnd = 9e9 end)
        pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
        for _, e in ipairs(Lighting:GetDescendants()) do if e:IsA("PostEffect") then pcall(function() e.Enabled = false end) end end
        pcall(function() local t = Workspace.Terrain; t.WaterWaveSize = 0; t.WaterWaveSpeed = 0; t.WaterReflectance = 0; t.WaterTransparency = 1 end)
        sweep(stripEffects)
        if not effConn then effConn = Workspace.DescendantAdded:Connect(function(o) if P.ReduceLag then stripEffects(o) end end) end
    else
        if effConn then effConn:Disconnect(); effConn = nil end
        pcall(function() if savedShadows ~= nil then Lighting.GlobalShadows = savedShadows end end)
        pcall(function() if savedFog ~= nil then Lighting.FogEnd = savedFog end end)
        pcall(function() if savedQuality ~= nil then settings().Rendering.QualityLevel = savedQuality end end)
    end
end
local function setNoTextures(on)
    P.NoTextures = on
